# Liebermann, Gesetze I p. 657: Lond 32 B 2–B 13 (insertion into ECf retr; cited as ECf 32 B 2 …)
D = lambda de, en: (de, en)
LOND_ED = 'This passage is not part of ECf or ECf retr: it is one of the additions of the London collection (Leges Anglorum s. XIII in. Londoniis collectae), which Liebermann prints across the page as an insertion into ECf retr. 32 (32 A–E, pp. 655–660). The dictionary cites it as “ECf 32 B …”, so it is kept with ECf here.'
SMALL = 'Liebermann prints the words borrowed from {src} in smaller type; his margin names the source ({m}).'
LD = D('<i>fehlt Ld</i>', 'lacking in Ld')
def L(n, text, notes, margin=None, small=None, extra=None):
    ed = [LOND_ED] + ([SMALL.format(src=small[0], m=small[1])] if small else []) + (extra or [])
    c = {'code': 'ECf', 'n': n, 'page': 657, 'keys': ['ECf ' + n], 'text': text, 'notes': notes, 'editorial': ed}
    if margin: c['margin'] = margin
    return c
